def list_products(*,enabled_only=False):
 items=[dict(x,capabilities=list(x["capabilities"])) for x in PRODUCTS]
 return [x for x in items if x["enabled"]] if enabled_only else items
def get_product(identifier):
 key=identifier.strip().casefold()
 if not key:return None
 for x in PRODUCTS:
  if key in {x["product_id"].casefold(),x["ecosystem_id"].casefold(),x["package_name"].casefold(),x["name"].casefold()}:return dict(x,capabilities=list(x["capabilities"]))
 return None
